{\n
  "additionalProperties": true, \n
  "type": "object", \n
  "description": "A single ERP5 document with fields and available actions.", \n
  "properties": {\n
    "prints": {\n
      "type": "array"\n
    }, \n
    "error": {\n
      "type": "string", \n
      "description": "Error message; present only on failure."\n
    }, \n
    "relative_url": {\n
      "type": "string"\n
    }, \n
    "parent": {\n
      "type": "string"\n
    }, \n
    "title": {\n
      "type": "string"\n
    }, \n
    "url": {\n
      "type": "string"\n
    }, \n
    "fields": {\n
      "type": "object"\n
    }, \n
    "portal_type": {\n
      "type": "string"\n
    }, \n
    "views": {\n
      "type": "array"\n
    }, \n
    "actions": {\n
      "type": "array"\n
    }, \n
    "all_editable": {\n
      "type": "boolean"\n
    }, \n
    "reports": {\n
      "type": "array"\n
    }, \n
    "workflows": {\n
      "type": "array"\n
    }, \n
    "fields_by_view": {\n
      "type": "object"\n
    }, \n
    "exchanges": {\n
      "type": "array"\n
    }, \n
    "jumps": {\n
      "type": "array"\n
    }, \n
    "all_listboxes": {\n
      "type": [\n
        "object", \n
        "null"\n
      ]\n
    }, \n
    "has_create_action": {\n
      "type": "boolean"\n
    }\n
  }\n
}

{
 "additionalProperties": false, 
 "required": [
 "relative_url"
 ], 
 "type": "object", 
 "properties": {
 "all_editable": {
 "default": 0, 
 "type": [
 "boolean", 
 "integer"
 ], 
 "description": "Fetch ALL views and return only editable fields grouped by view name (ignores 'view' when true)."
 }, 
 "relative_url": {
 "type": "string", 
 "description": "Document relative_url, e.g. person_module/1."
 }, 
 "view": {
 "default": "view", 
 "type": "string", 
 "description": "View/tab (default view)."
 }
 }
 }
